export const norm = s => String(s || "").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "")
  .replace(/[^a-z0-9 ]/g, "").replace(/\s+/g, " ").trim();

const TABLE = {};
for (const [prompt, list] of Object.entries(RAW)) {
  const byName = {}, byLast = {};
  for (const part of list.split(",")) {
    const m = part.trim().match(/^(.*\S)\s+(\d+)$/);
    if (!m) continue;
    const name = m[1].trim(), score = +m[2];
    if (!score) continue;
    const key = norm(name);
    byName[key] = { name, score };
    const last = key.replace(/ (jr|sr|ii|iii|iv)$/, "").split(" ").pop();
    (byLast[last] ||= []).push(key);
  }
  TABLE[prompt] = { byName, byLast };
}

// Look up an answer in the hand-built list. Returns {name, score} or null.
export function lookup(prompt, answer) {
  const t = TABLE[prompt];
  if (!t) return null;
  let key = norm(answer);
  if (ALIASES[key]) key = norm(ALIASES[key]);
  if (t.byName[key]) return t.byName[key];
  const noSuffix = key.replace(/ (jr|sr|ii|iii|iv)$/, "");
  for (const k of Object.keys(t.byName)) if (k.replace(/ (jr|sr|ii|iii|iv)$/, "") === noSuffix) return t.byName[k];
  // A unique last name alone counts (e.g. "Muresan"), but not common ones shared by several answers.
  const hits = t.byLast[noSuffix];
  if (!key.includes(" ") && key.length > 3 && hits && hits.length === 1) return t.byName[hits[0]];
  return null;
}

export function hasList(prompt) { return !!TABLE[prompt]; }
export function randomAnswer(prompt) {
  const t = TABLE[prompt];
  if (!t) return null;
  const all = Object.values(t.byName);
  return all[Math.floor(Math.random() * all.length)];
}
